 "previous_turns_for_context_only": [],
 "turns": [
  {
   "id": "M1:T1",
   "speaker": "Analyst",
   "act": "open",
   "guide": "Analyst opens the meeting about E-GOVERNANCE MISSION MODE PROJECT (MMP) CRIME & (meeting 1 of 1, kickoff)."
  },
  {
   "id": "M1:T2",
   "speaker": "Client",
   "act": "context",
   "guide": "Client gives the project background below, in their own words.",
   "content": [
    {
     "text": "The key guiding principle behind the functional design of CCTNS V1.0 is to focus on the critical functionality that provides value to the police personnel at the cutting edge which in turn can improve the outcomes in the areas of \"Investigation of Crime\" and \"Detection of Criminals\". CCTNS V1.0 functionality is designed to focus on delivering value to IOs, records room staff and citizens within the broad crime investigation area. Based on the guiding principles stated above, nine different function blocks have been identified and the detailed functionality of each block was determined.",
     "role": "background"
    }
   ]
  },
  {
   "id": "M1:T3",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'help module' and asks about it."
  },
  {
   "id": "M1:T4",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The solution should provide detailed context-sensitive help material for all the possible actions and scenarios on all user interfaces in the application.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'help module'."
  },
  {
   "id": "M1:T6",
   "speaker": "Client",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T7",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'general needs' and asks about it."
  },
  {
   "id": "M1:T8",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The solution should send alerts (e.g., email, SMS) to the user if the user chooses to whenever any action has been taken on the alert.",
     "role": "statement"
    },
    {
     "text": "The solution should enable the user to track the submitted defect or enhancement request.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T9",
   "speaker": "Analyst",
   "act": "echo",
   "guide": "Analyst paraphrases the content back as a question, to confirm understanding.",
   "content": [
    {
     "text": "The solution should enable the user to track the submitted defect or enhancement request.",
     "role": "echo"
    }
   ]
  },
  {
   "id": "M1:T10",
   "speaker": "Client",
   "act": "confirm",
   "guide": "Short confirmation that the paraphrase is right."
  },
  {
   "id": "M1:T11",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The solution should enable the help-desk user to view the reports on the submitted defects or enhancement requests category-wise, status-wise, and age- wise.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T12",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T13",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'general needs'."
  },
  {
   "id": "M1:T14",
   "speaker": "TechLead",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T15",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'audit module' and asks about it."
  },
  {
   "id": "M1:T16",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "An audit trail is a record of actions taken by either the user or the system triggers. This includes actions taken by users or Administrators, or actions initiated automatically by the system as a result of system parameters. The System must keep an unalterable audit trail capable of automatically capturing and storing information about: All the actions (create/read/update/delete) that are taken upon the critical entities (case, suspect, property,...) in the system The user initiating and or carrying out the action; The date and time of the event. Administrative parameters The word \"unalterable\" is to mean that the audit trail data cannot be modified in any way or deleted by any user; it may be subject to re-department and copying to removable media if required, so long as its contents remain unchanged.",
     "role": "statement"
    },
    {
     "text": "Once the audit trail functionality has been activated, the System must track events without manual intervention, and store in the audit trail information about them.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T17",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System must maintain the audit trail for as long as required, which will be at least for the life of the case to which it refers.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T18",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T19",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System must ensure that audit trail data is available for inspection on request, so that a specific event can be identified and all related data made accessible, and that this can be achieved by authorised external personnel who have little or no familiarity with the system.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T20",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System must be able to export audit trails for specified cases (without affecting the audit trail stored by the System). This functionality can be used by external auditors who wish to examine or analyse system activity.",
     "role": "statement"
    },
    {
     "text": "The System must at a minimum be able to provide reports for actions on cases organised: By case; By user; In chronological sequence.",
     "role": "statement"
    }
   ]
  }
 ]
}
